-- If there is a dedicated table that stores sellers
SELECT COUNT(*) AS seller_count
FROM sellers;

-- Average review score
SELECT AVG(score) AS average_review_score
FROM   reviews;

SELECT COUNT(*) AS orders_in_2017
FROM   orders
WHERE  strftime('%Y', order_date) = '2017';

/* Count the distinct customers whose city is Curitiba */
SELECT COUNT(DISTINCT c.customer_id) AS curitiba_customers
FROM   customers AS c
       /* If the city is stored in a separate address table, join it */
       LEFT JOIN addresses AS a
              ON c.address_id = a.address_id
WHERE  COALESCE(a.city, c.city) = 'Curitiba';

/*  Average review score for orders that contain more than one item  */
SELECT AVG(r.review_score) AS avg_review_score
FROM   Reviews r
JOIN (
        SELECT order_id
        FROM   OrderItems
        GROUP BY order_id
        HAVING COUNT(*) > 1          -- orders with > 1 item
     ) multi_item_orders
     ON r.order_id = multi_item_orders.order_id;

/*  Count the orders that contain items from more than one seller  */
SELECT COUNT(*) AS orders_with_multiple_sellers
FROM (
        /*  One row per order – keep only those that have >1 distinct seller  */
        SELECT oi.order_id
        FROM   order_items oi
               /*  If the seller is stored on the item record instead of
                   the order_items row, join to the items table:               */
               -- JOIN items i ON i.item_id = oi.item_id
        GROUP BY oi.order_id
        HAVING COUNT(DISTINCT 
                     /* replace with the correct column name:
                        - if seller_id is in order_items:  oi.seller_id
                        - if seller_id is in items:        i.seller_id   */
                     oi.seller_id) > 1
     ) AS multi_seller_orders;

/*  Total sales for last month  */
SELECT
    SUM(s.amount) AS total_sales_last_month
FROM
    sales AS s
WHERE
    /*  First day of last month  */
    s.sale_date >= date('now','-1 month','start of month')
    /*  First day of the current month (exclusive)  */
    AND s.sale_date <  date('now','start of month');

/*  How many different products have actually been sold?  */
SELECT COUNT(DISTINCT product_id) AS products_sold
FROM   sales;          -- or the table that records each sale (e.g. order_items)

/*  Count of female customers  */
SELECT COUNT(*) AS female_customer_count
FROM   customers
WHERE  LOWER(gender) = 'female';

/*  Most expensive item price that appears in any order  */
SELECT MAX(i.price) AS most_expensive_price
FROM   Items i
WHERE  EXISTS (
         SELECT 1
         FROM   OrderItems oi
         WHERE  oi.item_id = i.item_id
       );

/*  Count the distinct customers whose residence is in Curitiba  */
SELECT COUNT(DISTINCT c.customer_id) AS unique_customers_in_curitiba
FROM   customers      AS c
JOIN   addresses      AS a
       ON a.address_id = c.address_id          -- or the appropriate FK
WHERE  a.city = 'Curitiba';

/*  Count the orders that contain items from more than one seller  */
SELECT COUNT(*) AS orders_with_multiple_sellers
FROM (
        /*  One row per order – keep only those that have >1 distinct seller  */
        SELECT oi.order_id
        FROM   order_items oi
               /*  If the seller is stored on the item record, join to it  */
               /*  LEFT JOIN items i ON oi.item_id = i.item_id   */
        GROUP BY oi.order_id
        HAVING COUNT(DISTINCT oi.seller_id) > 1          -- or i.seller_id if joined
     ) AS multi_seller_orders;

-- Average review score
SELECT AVG(score) AS average_score
FROM   reviews;

/*  Count the orders that contain items from more than one seller  */
SELECT COUNT(*) AS orders_with_multiple_sellers
FROM (
        /*  One row per order – keep only those that have >1 distinct seller  */
        SELECT oi.order_id
        FROM   order_items oi
               /*  If the seller is stored on the item record, join to it  */
               /*  LEFT JOIN items i ON oi.item_id = i.item_id          */
        GROUP BY oi.order_id
        HAVING COUNT(DISTINCT oi.seller_id) > 1          -- or i.seller_id if joined
     ) AS multi_seller_orders;

SELECT COUNT(DISTINCT customer_id) AS unique_customers_in_curitiba
FROM customers
WHERE customer_city = 'Curitiba';
